def crear_pagos(apps, schema_editor):
    """Las cuentas cobradas antes del pago dividido tenían un solo medio:
    se les crea un PagoCuenta por su total para que la caja siga sumando igual."""
    Cuenta = apps.get_model("ventas", "Cuenta")
    PagoCuenta = apps.get_model("ventas", "PagoCuenta")
    cobradas = Cuenta.objects.filter(
        estado="CERRADA", total__gt=0, metodo_pago__isnull=False
    ).exclude(pagos__isnull=False)
    PagoCuenta.objects.bulk_create(
        PagoCuenta(cuenta=c, metodo=c.metodo_pago, monto=c.total) for c in cobradas
    )


def borrar_pagos(apps, schema_editor):
    apps.get_model("ventas", "PagoCuenta").objects.all().delete()


